// 1-bit wide, 256-to-1 multiplexer
module TopModule(
    input  [255:0] in,
    input  [7:0] sel,
    output out
);
    wire [0:255] wires;
    assign wires[0] = in[0];
    genvar i;
    for (i = 1; i < 256; i = i + 1) begin
        assign wires[i] = in[i];
    end
    assign out = wires[sel];
endmodule

